import test from 'node:test';
import assert from 'node:assert/strict';
import { normalizeId, listCustomers, getCustomer, mergeCustomers } from '../src/customers.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('normalizeId trims and uppercases', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
  assert.equal(normalizeId(' C-001 '), 'C-001');
  assert.equal(normalizeId('  c-001  '), 'C-001');
});

test('listCustomers returns all customers', () => {
  const customers = listCustomers();
  assert.ok(Array.isArray(customers));
  assert.ok(customers.length > 0);
  assert.ok(customers.some((c) => c.id === 'C-001'));
});

test('getCustomer retrieves by normalized id', () => {
  const result = getCustomer('c-001');
  assert.equal(result.ok, true);
  assert.equal(result.value.id, 'C-001');
  assert.equal(result.value.name, 'Northwind Studio');
});

test('getCustomer rejects unknown id', () => {
  const result = getCustomer('C-999');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers merges two customers', () => {
  const customers = listCustomers();
  const invoices = [];

  // Create invoices for C-001 and C-002
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const allInvoices = [issued1, issued2];

  // Merge C-001 into C-002
  const result = mergeCustomers(customers, allInvoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.some((c) => c.id === 'C-001'), false);
  assert.equal(result.value.customers.some((c) => c.id === 'C-002'), true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers with ID normalization', () => {
  const customers = listCustomers();
  const invoices = [];

  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const allInvoices = [issued1, issued2];

  // Merge with mixed case and whitespace
  const result = mergeCustomers(customers, allInvoices, ' c-001 ', ' C-002 ');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.some((c) => c.id === 'C-001'), false);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers rejects same customer', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-001');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers rejects same customer with normalization', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, ' c-001 ', 'C-001');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers rejects unknown fromId', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-999', 'C-001');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers rejects unknown intoId', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-999');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers with no invoices', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.customers.some((c) => c.id === 'C-001'), false);
});

test('mergeCustomers with multiple invoices from same customer', () => {
  const customers = listCustomers();

  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-03',
    lines: [{ sku: 'COPY-HOUR', qty: 2 }],
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2025-0001', 'INV-2025-0002']).value;

  const allInvoices = [issued1, issued2, issued3];

  const result = mergeCustomers(customers, allInvoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.filter((i) => i.customerId === 'C-001').length, 0);
  assert.equal(result.value.invoices.filter((i) => i.customerId === 'C-002').length, 3);
});

test('mergeCustomers preserves invoice details', () => {
  const customers = listCustomers();

  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = mergeCustomers(customers, [issued], 'C-001', 'C-002');

  const mergedInvoice = result.value.invoices[0];
  assert.equal(mergedInvoice.customerId, 'C-002');
  assert.equal(mergedInvoice.number, issued.number);
  assert.equal(mergedInvoice.issueDate, issued.issueDate);
  assert.equal(mergedInvoice.status, issued.status);
  assert.deepEqual(mergedInvoice.lines, issued.lines);
});

test('mergeCustomers does not mutate original arrays', () => {
  const customers = listCustomers();
  const originalCustomerCount = customers.length;

  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const invoices = [issued];
  const originalInvoiceCustomer = invoices[0].customerId;

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  // Original arrays should be unchanged
  assert.equal(customers.length, originalCustomerCount);
  assert.equal(customers.some((c) => c.id === 'C-001'), true);
  assert.equal(invoices[0].customerId, originalInvoiceCustomer);

  // Result should have changes
  assert.equal(result.value.customers.length, originalCustomerCount - 1);
  assert.equal(result.value.customers.some((c) => c.id === 'C-001'), false);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers with mixed invoice customers', () => {
  const customers = listCustomers();

  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-03',
    lines: [{ sku: 'COPY-HOUR', qty: 2 }],
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2025-0001', 'INV-2025-0002']).value;

  const allInvoices = [issued1, issued2, issued3];

  // Merge C-001 into C-002
  const result = mergeCustomers(customers, allInvoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002'); // was C-001
  assert.equal(result.value.invoices[1].customerId, 'C-002'); // already C-002
  assert.equal(result.value.invoices[2].customerId, 'C-003'); // unchanged
});

test('mergeCustomers with various invoice statuses', () => {
  const customers = listCustomers();

  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const draft = inv1;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  }).value;
  const issued = issueInvoice(inv2, []).value;

  const allInvoices = [draft, issued];

  const result = mergeCustomers(customers, allInvoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[0].status, 'draft');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
  assert.equal(result.value.invoices[1].status, 'issued');
});

test('mergeCustomers removes exactly one customer', () => {
  const customers = listCustomers();
  const originalCount = customers.length;

  const result = mergeCustomers(customers, [], 'C-001', 'C-002');

  assert.equal(result.value.customers.length, originalCount - 1);
});

test('mergeCustomers chain merge (merge A into B, then B into C)', () => {
  const customers = listCustomers();

  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-03',
    lines: [{ sku: 'COPY-HOUR', qty: 2 }],
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2025-0001', 'INV-2025-0002']).value;

  let allInvoices = [issued1, issued2, issued3];
  let updatedCustomers = customers;

  // First merge C-001 into C-002
  let result = mergeCustomers(updatedCustomers, allInvoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  updatedCustomers = result.value.customers;
  allInvoices = result.value.invoices;

  // Then merge C-002 into C-003
  result = mergeCustomers(updatedCustomers, allInvoices, 'C-002', 'C-003');
  assert.equal(result.ok, true);

  // All invoices should now belong to C-003
  assert.equal(result.value.invoices.filter((i) => i.customerId === 'C-003').length, 3);
  assert.equal(result.value.invoices.filter((i) => i.customerId === 'C-001').length, 0);
  assert.equal(result.value.invoices.filter((i) => i.customerId === 'C-002').length, 0);
});

